// Parse the response body
const users = pm.response.json();

// Test 1: Verify status code is 200
pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

// Test 2: Verify response is an array
pm.test("Response is an array", function () {
    pm.expect(users).to.be.an("array");
});

// Test 3: Verify array is not empty
pm.test("Users array is not empty", function () {
    pm.expect(users.length).to.be.above(0);
});

// Test 4: Verify required fields for every user
pm.test("Every user has ID, name and email", function () {
    users.forEach(function (user) {
        pm.expect(user).to.have.property("id");
        pm.expect(user).to.have.property("name");
        pm.expect(user).to.have.property("email");
    });
});

// Test 5: Save the first user's ID
pm.collectionVariables.set("userId", users[0].id);

console.log("Saved User ID:", users[0].id);

const response = pm.response.json();
const userId = Number(pm.collectionVariables.get("userId"));

pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Returned user ID matches requested ID", function () {
    pm.expect(response.id).to.eql(userId);
});

pm.test("Updated name is correct", function () {
    pm.expect(response.name).to.eql("Updated Test User");
});

pm.test("Phone number is not empty", function () {
    pm.expect(response.phone).to.not.be.empty;
});

pm.test("Email is updated", function () {
    pm.expect(response.email).to.eql("updateduser@example.com");
});

pm.test("Company name is updated", function () {
    pm.expect(response.company.name).to.eql("Updated Test Company");
});
